#!/bin/bash
set -e

# Stuck-queue-entry fix:
# - getQueues() now excludes ALL terminal statuses (was only excluding
#   'Done') and scopes to today only -- stale entries from a prior day
#   can no longer leak into the live queue view, even if Day Closing
#   gets skipped on some day.
# - Doctor consultation & Optometry assessment each get an 'Unable to
#   Complete This Visit' escape hatch (reason required) for visits that
#   can't reach the diagnosis / VA requirement -- doesn't weaken that
#   requirement for anyone else.
# - Day Closing's Close Day tab now shows a soft warning listing any
#   patients still open in Doctor/Optometry queues today, with a bulk
#   'close all with one shared reason' action. Doesn't block Close Day.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/(main)/queue"
echo "" | base64 -d > "app/(main)/queue/actions.js"
echo "Wrote app/(main)/queue/actions.js"

mkdir -p "app/consultation/[id]"
echo "" | base64 -d > "app/consultation/[id]/consultation-form.js"
echo "Wrote app/consultation/[id]/consultation-form.js"

mkdir -p "app/(main)/optometry/[id]"
echo "" | base64 -d > "app/(main)/optometry/[id]/optometry-workspace.js"
echo "Wrote app/(main)/optometry/[id]/optometry-workspace.js"

mkdir -p "app/(main)/cash-management"
echo "" | base64 -d > "app/(main)/cash-management/page.js"
echo "Wrote app/(main)/cash-management/page.js"

git add "app/(main)/queue/actions.js" "app/consultation/[id]/consultation-form.js" "app/(main)/optometry/[id]/optometry-workspace.js" "app/(main)/cash-management/page.js"
git commit -m "Fix stuck queue entries: exclude terminal statuses + scope to today; add force-close escape hatch; Day Closing warning"
git push

echo "Done."
